from lib import *
S = SS('s30')
steps = [
    step("默认 LinkExtractor().extract_links(response):页面有 <base href=\"http://site.test/docs/\">,相对链接 intro.html 解析成 http://site.test/docs/intro.html,/abs/path 则是 http://site.test/abs/path;重复的 intro.html 只留第一个(“Intro again” 被去掉);file.pdf、img.png 被默认的扩展名黑名单过滤;mailto: 和 javascript: 被丢弃;共 13 个。只看 <a> 和 <area> 的 href——iframe src、img src、<link href> 都不在其中。#frag(只有片段)被解析成 http://site.test/docs/#frag 保留下来。", t=tl(S(1)), mark=lidx(S(1), 'intro.html', '#frag', 'area'), done=lidx(S(1), '默认:13'), kv=KV([['基准 URL', '<base href> 优先'], ['重复链接', 'unique=True 只留第一个'], ['扩展名', '默认过滤 pdf、png 等'], ['mailto / javascript', '丢弃'], ['标签', '默认 a、area 的 href']], ['基准 URL'])),
    step("allow / deny 是对完整绝对 URL 的正则:allow=r'/abs|/nofollow' 只剩 2 个;deny=r'/(abs|ad|x)$' 去掉 /abs/path 以外还去掉 /ad 和 /x,剩 10 个;allow_domains='other.test' 只剩 other.test 的 1 个;deny_domains='other.test' 其余 12 个(默认 13 个,少了 other.test 的 1 个)。", t=tl(S(2)), mark=lidx(S(2), 'allow=', 'deny=', 'allow_domains', '总数'), kv=KV([['allow', '完整绝对 URL 上的正则,命中才留'], ['deny', '命中就去掉'], ['allow_domains / deny_domains', '按域名过滤'], ['deny_domains = other.test', '13 → 12 个']], ['allow'])),
    step("限定提取区域和标签:restrict_css='#nav' 只提取 #nav 里的 1 个;restrict_xpaths 取 div.ad 里的 1 个;restrict_text 按链接文字过滤,r'^nested|^Intro$' 留下 Intro 和 nested text 2 个;tags 加上 iframe、link,attrs 加上 src 就能取到 /frame 和 /area;tags='*', attrs='*'(通配符)共 21 个;tags='*', attrs='src', deny_extensions=[] 取到 iframe 的 /frame 和 img 的 /pic.jpg,再加 deny_tags='iframe' 就只剩 /pic.jpg。", t=tl(S(3)), mark=lidx(S(3), 'restrict_text', 'deny_tags', '总数'), done=lidx(S(3), 'restrict_css', 'restrict_xpaths'), kv=KV([['restrict_css / restrict_xpaths', '只在指定区域里找'], ['restrict_text', '按链接文字过滤'], ['tags / attrs / "*"', '扩大到 iframe、img 等,"*" 通配'], ['deny_tags / deny_attrs', '在通配基础上排除']], ['restrict_text'])),
    step("unique=True(默认)13 个,unique=False 变 14 个(多了重复的 intro.html);page?b=2&a=1 和 page?a=1&b=2 默认当作两个不同的链接都留着,canonicalize=True 后统一成 page?a=1&b=2 只剩 1 个;process_value 可以改写属性值,attrs=('onclick',) 配上从 onclick=\"go('/from-onclick')\" 里抠 URL 的函数,得到 http://site.test/from-onclick。", t=tl(S(4)), mark=lidx(S(4), 'canonicalize=True', 'process_value'), done=lidx(S(4), 'unique=True'), kv=KV([['unique', 'True 去重(13);False 保留重复(14)'], ['canonicalize=True', '参数排序,上面两个合并成 1 个'], ['process_value', '改写属性值,可从 onclick 里抽 URL']], ['canonicalize=True'])),
    step("扩展名黑名单:IGNORED_EXTENSIONS 共 91 个(前 12 个 7z、7zip、bz2、rar、tar、tar.gz、xz、zip、mng、pct、bmp、gif …)。deny_extensions=[] 时 file.pdf 和 img.png 都通过;deny_extensions=['pdf'] 只过滤 pdf,png 通过。", t=tl(S(5)), mark=lidx(S(5), 'deny_extensions=[]', "deny_extensions=[\"pdf\"]"), done=lidx(S(5), 'IGNORED_EXTENSIONS'), kv=KV([['默认', 'IGNORED_EXTENSIONS 共 91 个'], ['deny_extensions = []', '全部放行'], ['deny_extensions = ["pdf"]', '只过滤 pdf']], ['deny_extensions = []'])),
    step("几个细节:rel=\"nofollow\" 的链接照常被提取,只是 Link.nofollow = True(提取器不根据它过滤);href=\"#frag\" 被提取(解析成带片段的 URL),mailto: 和 javascript: 不会;<area href> 被提取;<a><b>nested</b> text</a> 的 text 是 'nested text'(嵌套标签的文字拼起来);Link 对象有 fragment、nofollow、text、url 四个字段。", t=tl(S(6)), mark=lidx(S(6), 'nofollow', 'Link 对象'), kv=KV([['rel="nofollow"', '照常提取,nofollow = True'], ['#frag', '被提取'], ['mailto / javascript', '不提取'], ['Link 字段', 'fragment、nofollow、text、url']], ['rel="nofollow"'])),
]
A = mkarts('s30', 30, 'Scrapy,LinkExtractor,链接提取,allow,restrict_css,canonicalize,真实验证,动画演示',
    '在一个含 base href、重复、pdf、mailto、nofollow 的页面上实测 LinkExtractor:默认 13 个链接;allow/deny 是完整 URL 上的正则;restrict_css、restrict_text 限定链接文字;tags="*" 通配;canonicalize 合并参数顺序不同的链接;91 个默认过滤的扩展名;nofollow 链接照常提取。',
    'LinkExtractor 是怎么把页面里的链接找出来并过滤的?<base> 怎么生效、重复怎么去、哪些扩展名默认被丢掉、allow 匹配的是什么、rel=nofollow 管不管?这篇用一个精心准备的页面把每个参数跑一遍。',
    [('13 个', '默认 LinkExtractor 在这个页面上提取到的链接数(tags="*"、attrs="*" 时是 21 个)'), ('91 个', 'IGNORED_EXTENSIONS 默认过滤的扩展名个数'), ('2.17.0', 'deny_tags、deny_attrs 加入的版本(源码文档注明)')],
    [('提取与解析', '<p>默认只看 <code>&lt;a&gt;</code> 和 <code>&lt;area&gt;</code> 的 <code>href</code>,用 <code>&lt;base&gt;</code> 或响应 URL 做基准把相对链接变成绝对链接,默认去重并过滤 mailto、javascript 和黑名单扩展名。</p>'),
     ('过滤', '<p><code>allow</code> / <code>deny</code> 是对完整绝对 URL 的正则;<code>allow_domains</code> / <code>deny_domains</code> 按域名。</p>'),
     ('区域与标签', '<p><code>restrict_css</code>、<code>restrict_xpaths</code> 限定在页面的某个区域里找;<code>tags</code>、<code>attrs</code> 扩展要看的标签和属性,支持 <code>"*"</code> 通配以及 <code>deny_tags</code> / <code>deny_attrs</code>(后两个在源码文档里标注为 2.17.0 加入)。</p>'),
     ('规范化', '<p><code>canonicalize=True</code> 把查询参数排序等规范化后再去重;<code>process_value</code> 可以改写属性值。</p>'),
     ('扩展名', '<p>默认丢掉 91 种扩展名(压缩包、图片、音视频、文档等);<code>deny_extensions</code> 可以自定义。</p>'),
     ('细节', '<p><code>nofollow</code> 只记录不过滤,片段链接会保留,文字取嵌套标签的全部文本。</p>')],
    steps,
    [ENV_Y + '。页面是手写的 HTML(含 <base>、重复链接、pdf/png、mailto/javascript、rel=nofollow、area、iframe、img、两个 div 区域);直接构造 HtmlResponse 后调用 extract_links,不经过网络',
     '没有验证:LinkExtractor 在 CrawlSpider 规则里与 process_links 的配合(见下一篇);很大的页面上的耗时;frame/iframe 里内容的抓取;<a> 之外的 data-href 等自定义属性的各种写法;XML/Atom 响应上的行为;allow 与 restrict_text 同时设置时的求值顺序(逻辑上是并集还是交集,只单独测了每个参数)'],
    '链接提取')
